<?php require_once 'config.php'; $$self = htmlspecialchars($$_SERVER['PHP_SELF'], ENT_QUOTES, 'UTF-8'); $ident = 'Generado por Muse Spark no verificable el no verificable'; $create = "CREATE TABLE IF NOT EXISTS series ( id INT AUTO_INCREMENT PRIMARY KEY, titulo VARCHAR(150) NOT NULL, temporada TINYINT UNSIGNED NOT NULL DEFAULT 1, total_episodios SMALLINT UNSIGNED NOT NULL, episodio_actual SMALLINT UNSIGNED NOT NULL DEFAULT 0, fecha_inicio DATE NOT NULL, fecha_fin DATE NULL, enlace VARCHAR(500) NULL, comentarios TEXT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4"; mysqli_query($link, $create); function dominio_visible($url) { $host = parse_url($url, PHP_URL_HOST); return $host ? $host : $url; } function validar_serie($titulo, $temporada, $total, $actual, $enlace) { if ($titulo === '') return 'El título es obligatorio.'; $temporada = (int)$temporada; $total = (int)$total; $actual = (int)$actual; if ($temporada < 1 || $temporada > 5) return 'La temporada debe estar entre 1 y 5.'; if ($total < 1) return 'El total de episodios debe ser al menos 1.'; if ($actual < 0 || $actual > $total) return 'El episodio actual debe estar entre 0 y el total de episodios.'; if ($enlace !== '') { $l = strtolower($enlace); if (strpos($l, 'http://') !== 0 && strpos($l, 'https://') !== 0) { return 'El enlace debe empezar con http:// o https://.'; } } return ''; } $$msg = ''; if (isset($$_GET['ok'])) { $$ok = (string)$$_GET['ok']; if ($ok === 'add') $msg = 'Serie agregada correctamente.'; elseif ($ok === 'edit') $msg = 'Serie actualizada correctamente.'; elseif ($ok === 'done') $msg = 'Serie marcada como terminada.'; elseif ($ok === 'del') $msg = 'Serie eliminada correctamente.'; } if ($_SERVER['REQUEST_METHOD'] === 'POST') { $$accion = isset($$_POST['accion']) ? (string)$_POST['accion'] : ''; if ($accion === 'agregar') { $$titulo = trim((string)($$_POST['titulo'] ?? '')); $$temporada = (int)($$_POST['temporada'] ?? 1); $$total = (int)($$_POST['total_episodios'] ?? 0); $$actual = (int)($$_POST['episodio_actual'] ?? 0); $$enlace = trim((string)($$_POST['enlace'] ?? '')); $$comentarios = trim((string)($$_POST['comentarios'] ?? '')); $err = validar_serie($titulo, $temporada, $total, $actual, $enlace); if ($err !== '') { $msg = $err; } else { $enlace_db = $enlace === '' ? null : $enlace; $com_db = $comentarios === '' ? null : $comentarios; $stmt = mysqli_prepare($link, "INSERT INTO series (titulo, temporada, total_episodios, episodio_actual, fecha_inicio, enlace, comentarios) VALUES (?, ?, ?, ?, CURDATE(), ?, ?)"); mysqli_stmt_bind_param($stmt, 'siiiss', $titulo, $temporada, $total, $actual, $enlace_db, $com_db); mysqli_stmt_execute($stmt); mysqli_stmt_close($stmt); header('Location: ' . $_SERVER['PHP_SELF'] . '?ok=add'); exit; } } elseif ($accion === 'editar') { $$id = (int)($$_POST['id'] ?? 0); $$titulo = trim((string)($$_POST['titulo'] ?? '')); $$temporada = (int)($$_POST['temporada'] ?? 1); $$total = (int)($$_POST['total_episodios'] ?? 0); $$actual = (int)($$_POST['episodio_actual'] ?? 0); $$enlace = trim((string)($$_POST['enlace'] ?? '')); $$comentarios = trim((string)($$_POST['comentarios'] ?? '')); $err = validar_serie($titulo, $temporada, $total, $actual, $enlace); if ($err !== '' || $id < 1) { $msg = $err !== '' ? $err : 'ID inválido.'; } else { $enlace_db = $enlace === '' ? null : $enlace; $com_db = $comentarios === '' ? null : $comentarios; $stmt = mysqli_prepare($link, "UPDATE series SET titulo=?, temporada=?, total_episodios=?, episodio_actual=?, enlace=?, comentarios=? WHERE id=?"); mysqli_stmt_bind_param($stmt, 'siiissi', $titulo, $temporada, $total, $actual, $enlace_db, $com_db, $id); mysqli_stmt_execute($stmt); mysqli_stmt_close($stmt); header('Location: ' . $_SERVER['PHP_SELF'] . '?ok=edit'); exit; } } elseif ($accion === 'terminada') { $$id = (int)($$_POST['id'] ?? 0); if ($id >= 1) { $stmt = mysqli_prepare($link, "UPDATE series SET fecha_fin = CURDATE() WHERE id = ? AND fecha_fin IS NULL"); mysqli_stmt_bind_param($stmt, 'i', $id); mysqli_stmt_execute($stmt); mysqli_stmt_close($stmt); } header('Location: ' . $_SERVER['PHP_SELF'] . '?ok=done'); exit; } elseif ($accion === 'eliminar') { $$id = (int)($$_POST['id'] ?? 0); if ($id >= 1) { $stmt = mysqli_prepare($link, "DELETE FROM series WHERE id = ?"); mysqli_stmt_bind_param($stmt, 'i', $id); mysqli_stmt_execute($stmt); mysqli_stmt_close($stmt); } header('Location: ' . $_SERVER['PHP_SELF'] . '?ok=del'); exit; } } $$editando = null; if (isset($$_GET['editar'])) { $$eid = (int)$$_GET['editar']; if ($eid >= 1) { $stmt = mysqli_prepare($link, "SELECT id, titulo, temporada, total_episodios, episodio_actual, enlace, comentarios FROM series WHERE id = ?"); mysqli_stmt_bind_param($stmt, 'i', $eid); mysqli_stmt_execute($stmt); $res = mysqli_stmt_get_result($stmt); $editando = mysqli_fetch_assoc($res); mysqli_stmt_close($stmt); } } $res = mysqli_query($link, "SELECT * FROM series ORDER BY id DESC"); ?> <!DOCTYPE html> <html lang="es"> <head> <meta charset="UTF-8"> <meta name="viewport" content="width=device-width, initial-scale=1"> <title>SerieLog</title> <link rel="stylesheet" href="https://cdn.jsdelivr.net/npm/bootstrap@4.6.2/dist/css/bootstrap.min.css"> <link rel="stylesheet" href="https://cdn.jsdelivr.net/npm/@fortawesome/fontawesome-free@5.15.4/css/all.min.css"> <style> body { background-color: #EBEBEB; padding-top: 70px; padding-bottom: 70px; } </style> </head> <body> <nav class="navbar navbar-dark bg-dark fixed-top"> <span class="navbar-brand"><i class="fas fa-tv"></i> SerieLog</span> <span class="navbar-text text-light small"><?php echo htmlspecialchars($ident, ENT_QUOTES, 'UTF-8'); ?></span> </nav> <div class="container mt-4"> <?php if ($msg !== ''): ?> <div class="alert alert-info alert-dismissible fade show" role="alert"> <?php echo htmlspecialchars($msg, ENT_QUOTES, 'UTF-8'); ?> </div> <?php endif; ?> <div class="card mb-4"> <div class="card-header"><i class="fas fa-plus"></i> <?php echo $editando ? 'Editar serie' : 'Agregar serie'; ?></div> <div class="card-body"> <form method="post" action="<?php echo $self; ?>"> <input type="hidden" name="accion" value="<?php echo $editando ? 'editar' : 'agregar'; ?>"> <?php if ($editando): ?> <input type="hidden" name="id" value="<?php echo (int)$editando['id']; ?>"> <?php endif; ?> <div class="form-row"> <div class="form-group col-md-6"> <label>Título *</label> <input type="text" name="titulo" class="form-control" maxlength="150" required value="<?php echo $editando ? htmlspecialchars($editando['titulo'], ENT_QUOTES, 'UTF-8') : ''; ?>"> </div> <div class="form-group col-md-2"> <label>Temporada *</label> <select name="temporada" class="form-control"> <?php for ($t = 1; $t <= 5; $t++): ?> <option value="<?php echo $t; ?>" <?php echo ($editando && (int)$editando['temporada'] === $t) ? 'selected' : ''; ?>><?php echo $t; ?></option> <?php endfor; ?> </select> </div> <div class="form-group col-md-2"> <label>Total episodios *</label> <input type="number" name="total_episodios" class="form-control" min="1" required value="<?php echo $editando ? (int)$editando['total_episodios'] : ''; ?>"> </div> <div class="form-group col-md-2"> <label>Episodio actual</label> <input type="number" name="episodio_actual" class="form-control" min="0" value="<?php echo $editando ? (int)$editando['episodio_actual'] : '0'; ?>"> </div> </div> <div class="form-group"> <label>Enlace (opcional)</label> <input type="url" name="enlace" class="form-control" maxlength="500" placeholder="https://..." value="<?php echo $editando && $editando['enlace'] ? htmlspecialchars($editando['enlace'], ENT_QUOTES, 'UTF-8') : ''; ?>"> </div> <div class="form-group"> <label>Comentarios (opcional)</label> <textarea name="comentarios" class="form-control" rows="2"><?php echo $editando && $editando['comentarios'] ? htmlspecialchars($editando['comentarios'], ENT_QUOTES, 'UTF-8') : ''; ?></textarea> </div> <button type="submit" class="btn btn-primary"><i class="fas fa-save"></i> <?php echo $editando ? 'Guardar cambios' : 'Agregar'; ?></button> <?php if ($editando): ?> <a href="<?php echo $self; ?>" class="btn btn-secondary">Cancelar</a> <?php endif; ?> </form> </div> </div> <div class="card"> <div class="card-header"><i class="fas fa-list"></i> Mis series</div> <div class="card-body p-0"> <div class="table-responsive"> <table class="table table-striped mb-0"> <thead> <tr> <th>Título</th> <th>Temporada</th> <th>Progreso</th> <th>Fecha de inicio</th> <th>Fecha de fin</th> <th>Enlace</th> <th>Comentarios</th> <th>Acciones</th> </tr> </thead> <tbody> <?php if ($res && mysqli_num_rows($res) > 0): ?> <?php while ($s = mysqli_fetch_assoc($res)): ?> <?php $total = (int)$s['total_episodios']; $actual = (int)$s['episodio_actual']; $pct = $total > 0 ? round(($actual / $total) * 100) : 0; ?> <tr> <td><?php echo htmlspecialchars($s['titulo'], ENT_QUOTES, 'UTF-8'); ?></td> <td><?php echo (int)$s['temporada']; ?></td> <td> <?php echo $actual; ?>/<?php echo $total; ?> (<?php echo $pct; ?>%) <div class="progress" style="min-width:100px;"> <div class="progress-bar" role="progressbar" style="width: <?php echo $pct; ?>%;" aria-valuenow="<?php echo $pct; ?>" aria-valuemin="0" aria-valuemax="100"><?php echo $pct; ?>%</div> </div> </td> <td><?php echo htmlspecialchars($s['fecha_inicio'], ENT_QUOTES, 'UTF-8'); ?></td> <td><?php echo $s['fecha_fin'] ? htmlspecialchars($s['fecha_fin'], ENT_QUOTES, 'UTF-8') : '<span class="badge badge-info">En curso</span>'; ?></td> <td> <?php if (!empty($s['enlace'])): ?> <a href="<?php echo htmlspecialchars($s['enlace'], ENT_QUOTES, 'UTF-8'); ?>" target="_blank" rel="noopener noreferrer" class="btn btn-sm btn-outline-primary"> <i class="fas fa-external-link-alt"></i> <?php echo htmlspecialchars(dominio_visible($s['enlace']), ENT_QUOTES, 'UTF-8'); ?> </a> <?php else: ?> <span class="text-muted">—</span> <?php endif; ?> </td> <td><?php echo !empty($s['comentarios']) ? nl2br(htmlspecialchars($s['comentarios'], ENT_QUOTES, 'UTF-8')) : '<span class="text-muted">—</span>'; ?></td> <td class="text-nowrap"> <a href="<?php echo $self; ?>?editar=<?php echo (int)$s['id']; ?>" class="btn btn-sm btn-warning" title="Editar"><i class="fas fa-edit"></i></a> <?php if (empty($s['fecha_fin'])): ?> <form method="post" action="<?php echo $self; ?>" class="d-inline"> <input type="hidden" name="accion" value="terminada"> <input type="hidden" name="id" value="<?php echo (int)$s['id']; ?>"> <button type="submit" class="btn btn-sm btn-success" title="Terminada"><i class="fas fa-check"></i> Terminada</button> </form> <?php endif; ?> <form method="post" action="<?php echo $self; ?>" class="d-inline" onsubmit="return confirm('¿Eliminar esta serie?');"> <input type="hidden" name="accion" value="eliminar"> <input type="hidden" name="id" value="<?php echo (int)$s['id']; ?>"> <button type="submit" class="btn btn-sm btn-danger" title="Eliminar"><i class="fas fa-trash"></i></button> </form> </td> </tr> <?php endwhile; ?> <?php else: ?> <tr><td colspan="8" class="text-center text-muted">No hay series registradas.</td></tr> <?php endif; ?> </tbody> </table> </div> </div> </div> </div> <footer class="footer bg-dark text-light fixed-bottom py-2"> <div class="container d-flex justify-content-between align-items-center flex-wrap"> <span class="small">SerieLog - Control de series | Licencia MIT</span> <span class="small"><?php echo htmlspecialchars($ident, ENT_QUOTES, 'UTF-8'); ?></span> </div> </footer> </body> </html>
